"""Core Backgrounds and associated traits, original PDF186–196 reviewed visually."""
import json,sys,copy
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1]);out=repo/'scripts/reviewed-content';source=next(s for s in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if s['id']=='core-v5')
general_pt='Antecedentes representam relações, circunstâncias e bens externos. Explique como os adquiriu e quem ou o que representam. Podem existir vários vínculos do mesmo tipo, adquiridos separadamente. O Narrador conduz as pessoas e consequências narrativas; não são servos automáticos. Compras com XP custam 3 por ponto adquirido. Modificadores descritos aqui não são aplicados automaticamente às rolagens.'
general_en='Backgrounds represent external relationships, circumstances and assets. Explain how they were acquired and who or what they represent. Several connections of the same type may be purchased separately. The Storyteller portrays people and narrative consequences; they are not automatic servants. XP purchases cost 3 per acquired dot. Modifiers described here are not automatically applied to rolls.'
def add(slug,pt,en,kind,pages,body,body_en,ratings,repeat=False,requirements=None,extra='',extra_en='',aliases=()):
 id='core-background-'+slug;versions=[]
 for suffix,level,label,label_en,text,text_en,req in ratings:
  requirements_v=copy.deepcopy(requirements or {});requirements_v.update(req)
  if repeat:requirements_v['repeatableInstances']=True
  sections={locale:[{'title':'Sistema' if locale=='pt-BR' else 'System','text':base},{'title':'Escolha e valor' if locale=='pt-BR' else 'Choice and rating','text':f'{level} '+('ponto(s). ' if locale=='pt-BR' else 'dot(s). ')+rule},{'title':'Preenchimento e uso' if locale=='pt-BR' else 'Selection and use','text':(general_pt if locale=='pt-BR' else general_en).replace('Compras com XP custam 3 por ponto adquirido.','O valor impresso conta como pontos de Defeito, respeitando o pacote de criação.').replace('XP purchases cost 3 per acquired dot.','The printed rating counts as Flaw dots, subject to the creation package.') if kind=='flaw' else general_pt if locale=='pt-BR' else general_en}] for locale,base,rule in [('pt-BR',body,text),('en',body_en,text_en)]}
  if extra:
   sections['pt-BR'].append({'title':'Exceções','text':extra});sections['en'].append({'title':'Exceptions','text':extra_en})
  versions.append({'id':id+'-core-v5-'+str(suffix),'book':'core-v5','level':level,'names':{'pt-BR':pt+' — '+label,'en':en+' — '+label_en},'sourceTitle':'Livro Básico V5, pp. '+', '.join(str(p-2) for p in pages)+' · '+label,'sourceLanguage':'pt-BR','pdfSha256':source['sha256'],'pages':[{'pdfPage':p,'printedPage':p-2} for p in pages],'requirements':requirements_v,'descriptions':sections})
 entry={'id':id,'kind':kind,'names':{'pt-BR':pt,'en':en},'aliases':list(dict.fromkeys([pt,en]+list(aliases)+[n for v in versions for n in v['names'].values()])),'versions':versions}
 if len(versions)==1:entry['level']=versions[0]['level']
 (out/(id+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
def levels(rows):return [(i,i,f'{i} ponto(s)',f'{i} dot(s)',pt,en,{}) for i,(pt,en) in enumerate(rows,1)]
def fixed(level,pt,en):return [(level,level,f'{level} ponto(s)',f'{level} dot(s)',pt,en,{})]
models_pt='Modelos de mortais (p. 185): Fraco — Atributos: dois 2, demais 1; Habilidades: três 2, cinco 1; sem Vantagens. Médio — Atributos: dois 3, três 2, demais 1; Habilidades: três 3, quatro 2, cinco 1; até 3 Vantagens e no máximo 2 Defeitos. Talentoso — Atributos: um 4, dois 3, dois 2, demais 1; Habilidades: duas 4 (uma com Especialização), quatro 3, quatro 2, quatro 1; até 10 Vantagens e no máximo 4 Defeitos. Mortífero — Atributos: dois 5, dois 4, dois 3, demais 2; Habilidades: uma 5, três 4, cinco 3, seis 2 e três Especializações; até 15 Vantagens, sem Defeitos. O Narrador pode usar pontos de Vantagens para comprar mais Habilidades.'
models_en='Mortal templates (p. 185): Weak — Attributes: two 2, others 1; Skills: three 2, five 1; no Advantages. Average — Attributes: two 3, three 2, others 1; Skills: three 3, four 2, five 1; up to 3 Advantages and at most 2 Flaws. Gifted — Attributes: one 4, two 3, two 2, others 1; Skills: two 4 (one with a specialty), four 3, four 2, four 1; up to 10 Advantages and at most 4 Flaws. Deadly — Attributes: two 5, two 4, two 3, others 2; Skills: one 5, three 4, five 3, six 2 and three specialties; up to 15 Advantages, no Flaws. The Storyteller may spend Advantage dots on more Skills.'
effect_pt=['Mortal Fraco, pouco útil em violência.','Mortal Médio ou grupo unido de mortais Fracos.','Mortal Talentoso ou grupo perigoso de mortais Médios.','Mortal Mortífero, Talentoso com magia/poderes sobrenaturais ou grupo bem armado de Talentosos.']
effect_en=['Weak mortal, of little use in violence.','Average mortal or cohesive group of Weak mortals.','Gifted mortal or dangerous group of Average mortals.','Deadly mortal, Gifted mortal with magic/supernatural powers, or well-armed group of Gifted mortals.']
reliability_pt=['Aparece quando o Narrador decidir, provavelmente ao menos uma vez por história.','Atende a metade dos chamados.','Ao ser chamado, aparece em 1–10 horas, determinadas por um dado.','Ao ser chamado, aparece tão rápido quanto possível.']
reliability_en=['Appears when the Storyteller decides, probably at least once per story.','Answers half of calls.','When called, appears in 1–10 hours, determined by one die.','When called, appears as soon as possible.']
allies=[]
for effectiveness in range(1,5):
 for reliability in range(4):
  cost=effectiveness+reliability
  if cost<=6:allies.append((f'e{effectiveness}-r{reliability}',cost,f'Efetividade {effectiveness}, Confiabilidade {reliability}',f'Effectiveness {effectiveness}, Reliability {reliability}',effect_pt[effectiveness-1]+' '+reliability_pt[reliability],effect_en[effectiveness-1]+' '+reliability_en[reliability],{}))
add('allies','Aliados','Allies','background',[186,187],
'Mortais que o apoiam voluntariamente: família, amigos ou organizações leais. Costumam ajudar uma vez por história, têm problemas próprios e esperam reciprocidade. Some Efetividade e Confiabilidade, no máximo 6 pontos por Aliado. Grupos aparecem em quantidade equivalente ao número de personagens jogadores. Registre cada pessoa ou grupo separadamente no Mapa de Relacionamentos.',
'Mortals who voluntarily support you: family, friends or loyal organizations. Usually help once per story, have their own concerns and expect reciprocity. Add Effectiveness and Reliability, at most 6 dots per Ally. Groups appear in numbers comparable to the number of player characters. Record each person or group separately on the Relationship Map.',allies,repeat=True,extra=models_pt,extra_en=models_en)
add('enemies','Inimigo','Enemy','flaw',[186,187],
'O oposto de Aliados. Cada Inimigo fornece pontos de Defeito iguais à Efetividade menos 2. Todos têm a mesma Confiabilidade: aparecem quando o Narrador julgar adequado, provavelmente ao menos uma vez por história. Podem ser criados pelos Modelos Mortais e registrados no Mapa de Relacionamentos.',
'The opposite of Allies. Each Enemy provides Flaw dots equal to Effectiveness minus 2. All share Reliability: appear when the Storyteller considers appropriate, probably at least once per story. May use Mortal templates and belong on the Relationship Map.',[
('gifted',1,'Efetividade 3','Effectiveness 3',effect_pt[2],effect_en[2],{}),('deadly',2,'Efetividade 4','Effectiveness 4',effect_pt[3],effect_en[3],{})],repeat=True,extra=models_pt,extra_en=models_en,aliases=['Inimigos','Enemies'])
add('contacts','Contatos','Contacts','background',[187],
'Pessoas humanas em posições adequadas para obter informações em áreas de especialização, frequentemente em troca de favores. Para outros tipos de ajuda, use Influência, Aliados ou Mawla. Pode definir um Contato ao comprá-lo ou quando precisar dele; acrescente-o ao Mapa de Relacionamentos.',
'Human people positioned to obtain information in specialized areas, often in exchange for favors. For other help use Influence, Allies or Mawla. May define a Contact on purchase or when first needed; add the Contact to the Relationship Map.',levels([
('Obtém algo barato ou comum, equivalente a Recursos 1: vendedor de maconha ou de carros.','Can obtain something cheap or common, equivalent to Resources 1: a cannabis or car dealer.'),
('Obtém algo útil, equivalente a Recursos 2: pequeno traficante de armas ou veterinário.','Can obtain something useful, equivalent to Resources 2: a small-time arms dealer or veterinarian.'),
('Obtém algo caro ou difícil, equivalente a Recursos 4: especialista em segurança, gerente de homicídios ou narcóticos.','Can obtain something expensive or difficult, equivalent to Resources 4: a security specialist, homicide or narcotics manager.')]),repeat=True,aliases=['Contatos criminosos'])
fame_rows=[('Uma subcultura distinta o conhece e admira.','A distinct subculture knows and admires you.'),('Celebridade local reconhecida por muitas pessoas da cidade.','Local celebrity recognized by many people in the city.'),('A maioria das pessoas no país conhece ao menos seu nome.','Most people in the country know at least your name.'),('Todos interessados em tendências sociais ou na sua área sabem algo sobre você.','Everyone interested in social trends or your field knows something about you.'),('Públicos nacionais ou globais: grande estrela de cinema/rock/estádios ou ex-presidente.','National or global audiences: a major film/rock/stadium star or former president.')]
fame=[]
for audience,pt_a,en_a in [('mortals','Mortais','Mortals'),('kindred','Membros','Kindred')]:
 for level,(pt,en) in enumerate(fame_rows,1):fame.append((f'{audience}-{level}',level,f'{pt_a}, {level} ponto(s)',f'{en_a}, {level} dot(s)',pt,en,{}))
add('fame','Fama','Fame','background',[188,189],
'A Fama pode substituir uma Característica em um teste Social, especialmente para acesso exclusivo, a critério do Narrador. Cada nível reduz em 1 a Dificuldade de testes Sociais contra fãs e de muitos testes de caça, conforme a estratégia. Também dificulta seguir alguém discretamente e pode atrair fãs ao refúgio. Considere Especialização em Disfarce. Normalmente afeta mortais; Fama entre Membros é comprada separadamente pelo mesmo custo.',
'Fame may replace a trait in a Social test, especially for exclusive access, at the Storyteller’s discretion. Each level reduces Social test Difficulty against fans and many hunting tests by 1, depending on strategy. It also makes discreetly following someone harder and may attract fans to the haven. Consider a Disguise specialty. Normally affects mortals; Fame among Kindred is purchased separately at the same cost.',fame,repeat=True)
add('dark-secret','Segredo Sombrio','Dark Secret','flaw',[188,189],
'Versão secreta da Infâmia: atos obscuros são desconhecidos, salvo por você e talvez um ou dois inimigos motivados. Fornece um ponto a menos que a Infâmia equivalente. Detalhe o segredo e quem pode descobri-lo. Consequências dependem da história e do Narrador.',
'A secret form of Infamy: dark deeds remain unknown except to you and perhaps one or two motivated enemies. Provides one fewer dot than equivalent Infamy. Describe the secret and who might uncover it. Consequences depend on the story and Storyteller.',fixed(1,'Segredo com risco equivalente à Infâmia 2; pode envolver violações graves da Máscara.','A secret with risk equivalent to Infamy 2; may involve serious Masquerade violations.'),repeat=True,aliases=['Segredo Sombrio: risco à Máscara','Segredo Sombrio: Trinchador'])
add('influence','Influência','Influence','background',[189],
'Influência na comunidade mortal por riqueza, prestígio, política, extorsão ou manipulação. Aplica-se a um grupo ou grande região da cidade; na cidade inteira vale um ponto a menos. Outra cidade na mesma região pode impor mais −1, e assim por diante. O Narrador pode substituir uma Característica por Influência, sobretudo para lidar com burocratas. Não permite iniciar guerras mundiais. Para crônicas de líderes globais, o Narrador pode recalibrar o alcance para nacional em 4 e global em 5.',
'Influence in mortal society through wealth, prestige, politics, extortion or manipulation. Applies to one group or large city area; citywide it counts one dot lower. Another city in the same region may impose another −1, and so on. The Storyteller may replace a trait with Influence, especially for dealing with bureaucrats. Does not allow starting world wars. For global-leader chronicles the Storyteller may recalibrate to national at 4 and global at 5.',levels([
('Bem-Relacionado: uma audiência respeitosa é garantida.','Well-connected: guaranteed a respectful hearing.'),('Influente: as pessoas querem lhe fazer favores.','Influential: people want to do favors for you.'),('Estabelecido: poderes e facções mortais hesitam em se opor.','Entrenched: mortal powers and factions hesitate to oppose you.'),('Poderoso: funcionários e soldados rasos obedecem, salvo boa razão em contrário.','Powerful: officials and rank-and-file obey unless they have good reason not to.'),('Dominante: figuras menores tentam antecipar e realizar seus desejos.','Dominant: lesser figures try to anticipate and fulfill your wishes.')]),repeat=True)
for slug,pt,en,dots,rule,rule_en in [
('despised','Desprezado','Despised',2,'Um grupo ou região o frustra e à sua facção. −2 dados para convencer alguém neutro a apoiá-lo politicamente ou fazer um favor. O Narrador deve envolver seus detratores na história.','A group or area works against you and your faction. −2 dice to convince a neutral individual to support you politically or do a favor. The Storyteller should involve detractors in the story.'),
('disliked','Malquisto','Disliked',1,'−1 dado em testes Sociais envolvendo qualquer grupo da cidade, exceto seus Contatos, Aliados e apoiadores explicitamente leais.','−1 die on Social tests involving any city group, except Contacts, Allies and explicitly loyal supporters.')]:
 add(slug,pt,en,'flaw',[189],rule,rule_en,fixed(dots,rule,rule_en),repeat=True)
haven_id='core-background-haven';no_haven_id='core-background-no-haven'
add('haven','Refúgio','Haven','background',[189,190],
'O valor de Refúgio Base representa tamanho, segurança e privacidade. Cada ponto acrescenta +1 à Dificuldade ou +1 dado à resistência contra detectar, invadir ou vigiar o local. O residente recebe +1 dado por ponto para perceber perigo dentro dele, inclusive testes para despertar. Sem este Antecedente ainda pode descansar em um local precário; outros Antecedentes podem justificar um lugar melhor. Refúgio não exige Recursos. Qualidades e Defeitos específicos somam ao valor para projetos e outros usos. Pode ser compartilhado pela coterie.',
'Base Haven represents size, security and privacy. Each dot adds +1 Difficulty or +1 resistance die against detecting, invading or surveilling it. The resident gains +1 die per dot to notice danger within, including waking tests. Without this Background one may still rest in a precarious place; other Backgrounds may justify better accommodation. Haven does not require Resources. Specific Merits and Flaws add to the rating for projects and other uses. May be shared by the coterie.',levels([
('Pequeno, mais seguro/privativo que o padrão: porão, cripta, depósito ou armazém.','Small but safer/more private than standard: basement, crypt, storage space or warehouse.'),('Bom tamanho, segurança ou privacidade: casa familiar, casa geminada, recinto de lobos ou ramificação de esgoto.','Good size, security or privacy: family home, townhouse, wolf enclosure or sewer branch.'),('Muito grande, seguro ou privativo: complexo afastado, banco ou estação de metrô desativada.','Very large, secure or private: remote compound, bank or disused subway station.')]),repeat=True,requirements={'incompatibleItems':[no_haven_id]})
add('no-haven','Nenhum Refúgio','No Haven','flaw',[190],
'Precisa fazer algum esforço, ao menos um teste básico, para encontrar um novo lugar de descanso a cada manhã.',
'Must make some effort, at least a basic test, to find a new resting place each morning.',fixed(1,'Não possui local estável de descanso.','Has no stable resting place.'),requirements={'incompatibleItems':[haven_id],'creationExcludedClans':['Ravnos']})
for slug,pt,en,level,rule,rule_en in [
('compromised','Refúgio: Comprometido','Haven: Compromised',2,'Já foi invadido e provavelmente consta em uma lista de vigilância. Invasores/espiões recebem +2 dados para invadir ou vigiar. Se a Inquisição o localizar, considere mudar.','Already breached and probably on a watchlist. Intruders/spies gain +2 dice to enter or surveil. Consider moving if the Inquisition identifies it.'),
('creepy','Refúgio: Assustador','Haven: Creepy',1,'Parece o covil de um assassino em série. Vizinhos podem denunciá-lo; −2 dados em testes Sociais para seduzir ou deixar hóspedes humanos à vontade.','Looks like a serial killer’s lair. Neighbors may report it; −2 dice on Social tests to seduce or relax human guests.'),
('haunted','Refúgio: Assombrado','Haven: Haunted',1,'Abriga manifestação sobrenatural que não controla ou entende. Alguém que a compreenda pode violar a segurança. O Narrador define os demais efeitos, impondo ao menos −1 dado por ponto deste Defeito às paradas afetadas realizadas no refúgio.','Contains a supernatural manifestation you do not control or understand. Someone understanding it may bypass security. The Storyteller determines other effects, imposing at least −1 die per Flaw dot on affected pools used in the haven.')]:
 add(slug,pt,en,'flaw',[190],rule,rule_en,fixed(level,rule,rule_en),repeat=True,requirements={'itemRatings':{haven_id:1}})
haven_traits=[
('hidden-armory','Arsenal Oculto','Hidden Armory',190,1,'Cada ponto fornece uma pistola e uma arma de fogo longa, com munição. O arsenal é tão protegido de descobertas quanto o refúgio.','Each dot supplies a pistol and a long firearm with ammunition. The armory is as protected against discovery as the haven.'),
('cell','Cela','Cell',190,2,'Começa com espaço trancado para dois prisioneiros, Dificuldade básica de fuga 5. Cada ponto extra dobra os prisioneiros, até 32 somente em refúgios muito grandes, OU acrescenta +1 à Dificuldade de fuga. Escolha o benefício de cada ponto e registre-o nas notas. Não disponível em refúgios pequenos.','Starts with a locked space for two prisoners, base escape Difficulty 5. Each extra dot doubles prisoners, up to 32 only in very large havens, OR adds +1 escape Difficulty. Choose and record each dot’s benefit in notes. Not available in small havens.'),
('watchmen','Vigilância','Watchmen',190,1,'Cada ponto fornece quatro guardas Médios e um chefe Talentoso. Guardas privados ou bandidos armados podem atrair atenção indesejada. Use os Modelos Mortais da p. 185.','Each dot supplies four Average guards and one Gifted leader. Private guards or armed thugs may attract unwanted attention. Use the Mortal templates on p. 185.'),
('laboratory','Laboratório','Laboratory',191,2,'Laboratório equipado. Cada ponto acrescenta +1 dado em rolagens de uma Especialização de Ciência ou Tecnologia, ou Alquimia de Sangue-Ralo pelo método Fixatio. Indique a Especialização. Não disponível em refúgios pequenos.','Equipped laboratory. Each dot adds +1 die to rolls using a Science or Technology specialty, or Thin-blood Alchemy using Fixatio. Specify the specialty. Not available in small havens.'),
('library','Biblioteca','Library',191,1,'Biblioteca especializada. Cada ponto acrescenta +1 dado em pesquisas ligadas a uma Especialização de Erudição, Investigação ou Ocultismo. Em refúgios pequenos, no máximo 1 ponto. Indique a Especialização.','Specialized library. Each dot adds +1 die to research using an Academics, Investigation or Occult specialty. Small havens allow at most 1 dot. Specify the specialty.'),
('postern','Poterna','Postern',191,1,'Saída discreta, túnel secreto ou acesso ao esgoto. Cada ponto acrescenta +1 dado para fugir ou escapar de vigilância próxima ao refúgio.','Discreet back exit, secret tunnel or sewer access. Each dot adds +1 die to flee or escape surveillance near the haven.'),
('security-system','Sistema de Segurança','Security System',191,1,'Sistema acima da média. Cada ponto acrescenta +1 dado para resistir a uma entrada não autorizada ou ser alertado sobre ela.','Above-average security system. Each dot adds +1 die to resist or be alerted to unauthorized entry.'),
('warding','Proteção','Warding',191,1,'Proteção mágica contra forças sobrenaturais. Talvez não consiga desativá-la, mas pode transitar pelo local. Combine os limites com o Narrador. Cada ponto acrescenta +1 dado para resistir a vigilância sobrenatural e a outras invasões que o Narrador permita impedir. Ele pode exigir Ocultismo 3+ ou Feitiçaria de Sangue.','Magical protection against supernatural forces. You may be unable to deactivate it but can move through the site. Agree its limits with the Storyteller. Each dot adds +1 die against supernatural surveillance and other intrusions the Storyteller allows it to prevent. The Storyteller may require Occult 3+ or Blood Sorcery.')]
for slug,pt,en,page,min_haven,rule,rule_en in haven_traits:
 rows=[]
 for level in range(1,6):
  minimum=max(min_haven,2 if slug=='library' and level>1 else 1)
  rows.append((level,level,f'{level} ponto(s)',f'{level} dot(s)',rule,rule_en,{'itemRatings':{haven_id:minimum}}))
 add('haven-'+slug,'Refúgio: '+pt,'Haven: '+en,'merit',[187,190] if slug=='watchmen' else [190,191] if page==191 else [190],rule,rule_en,rows,repeat=True,extra='Identifique nas escolhas o Refúgio específico e os benefícios de cada ponto. '+(models_pt if slug=='watchmen' else ''),extra_en='Identify the specific Haven and each dot’s benefits in the choices. '+(models_en if slug=='watchmen' else ''))
for slug,pt,en,min_haven,rule,rule_en in [
('location','Localização','Location',1,'Escolha +2 dados ou +2 à Dificuldade inimiga para benefícios relevantes de Chasse OU de Refúgio Base. Alternativamente, combine outro bônus situacional de dois dados com o Narrador, como Etiqueta no Elísio ou descobrir rumores na corte.','Choose +2 dice or +2 enemy Difficulty for relevant Chasse OR Base Haven benefits. Alternatively agree another situational two-die bonus with the Storyteller, such as Elysium Etiquette or court rumors.'),
('luxury','Luxo','Luxury',1,'+2 dados em testes Sociais com hóspedes mortais no refúgio. Se não tiver Recursos 3+, a decoração foi adquirida ilegalmente.','+2 dice on Social tests involving mortal guests in the haven. Without Resources 3+, the furnishings were acquired illegally.'),
('operating-room','Sala de Operações','Surgery',2,'Instalação de cirurgia de campanha ou melhor. +2 dados em testes relevantes, geralmente Medicina, no refúgio. Não disponível em refúgios pequenos.','Field surgery facilities or better. +2 dice on relevant tests, usually Medicine, in the haven. Not available in small havens.')]:
 add('haven-'+slug,'Refúgio: '+pt,'Haven: '+en,'merit',[191],rule,rule_en,fixed(1,rule,rule_en),repeat=True,requirements={'itemRatings':{haven_id:min_haven}})
herd_id='core-background-herd';obvious_id='core-background-obvious-predator'
add('herd','Rebanho','Herd','background',[191,192],
'Grupo de bolsas de quem se alimenta sem preocupação. Pode prestar serviços simples, mas não é tão controlado nem leal quanto Lacaios; use mortais Fracos e Médios se necessário. Toda semana pode saciar Fome igual ao valor de Rebanho sem rolar, benefício compartilhável entre vampiros. Alimentação excessiva pode reduzir o valor ao matar ou afugentar integrantes.',
'A group of vessels for safe feeding. May perform simple services but is less controlled and loyal than Retainers; use Weak and Average mortals if needed. Each week may slake Hunger equal to Herd without rolling, a benefit shareable among vampires. Overfeeding may reduce the rating by killing or driving members away.',levels([
('1–3 bolsas, Ressonância aleatória e sem Discrasias. Uma vez por mês pode mudar a Ressonância de uma vítima com Manipulação + Sagacidade, Dificuldade 4.','1–3 vessels, random Resonance and no Dyscrasias. Once per month may change one vessel’s Resonance with Manipulation + Insight, Difficulty 4.'),
('4–7 bolsas; metade compartilha uma Ressonância escolhida ao adquirir o Antecedente.','4–7 vessels; half share a Resonance chosen when buying the Background.'),
('7–15 bolsas; escolhe duas Ressonâncias diferentes a cada semana ao variar os integrantes de quem bebe.','7–15 vessels; choose two different Resonances each week by varying the members fed upon.'),
('16–30 bolsas; duas Ressonâncias por semana. Manutenção, encobrimentos e recrutamento entram ocasionalmente na crônica.','16–30 vessels; two Resonances per week. Maintenance, cover-ups and recruitment occasionally enter the chronicle.'),
('31–60 bolsas; três Ressonâncias por semana. Manutenção e recrutamento começam a ameaçar a Máscara.','31–60 vessels; three Resonances per week. Maintenance and recruitment start threatening the Masquerade.')]),repeat=True,requirements={'incompatibleItems':[obvious_id]})
add('obvious-predator','Predador Manifesto','Obvious Predator','flaw',[191],
'Humanos sentem instintivamente seu comportamento predatório. −2 dados em caça, exceto ações puramente Físicas de espreitar, perseguir e matar; −1 dado em qualquer teste Social para deixar humanos à vontade. Não pode manter Rebanho.',
'Humans instinctively sense predatory behavior. −2 dice to hunt, except purely Physical stalking, chasing and killing; −1 die on any Social test to put humans at ease. Cannot maintain a Herd.',fixed(2,'Defeito de alimentação e interação social.','Feeding and social interaction Flaw.'),requirements={'incompatibleItems':[herd_id]},aliases=['Rebanho: Predador Óbvio','Predador Óbvio'])
mask_id='core-background-mask'
add('mask','Máscara','Mask','background',[192,194],
'Identidade para circular na sociedade mortal e explicar a vida noturna. Pode manter várias Máscaras separadas, com seus riscos. Sem pontos, pode ter uma identidade falsa que sustente apenas verificações superficiais, sem resistir a antecedentes ou investigação detalhada.',
'An identity for moving through mortal society and explaining a nocturnal life. May maintain separate Masks with their attendant risks. With no dots, may have a false identity supporting only superficial checks, not background checks or detailed investigation.',levels([
('Boa identidade falsa com crédito, conta bancária, histórico de crédito e certidão de nascimento; passa em antecedentes estaduais ou municipais.','Good false identity with credit, bank account, credit history and birth certificate; passes state or municipal background checks.'),
('Passa em antecedentes federais, como FBI ou Scotland Yard. Registro militar ou de inteligência de sua vida mortal fica classificado como confidencial.','Passes federal checks such as the FBI or Scotland Yard. Military or intelligence records from mortal life become classified.')]),repeat=True)
for slug,pt,en,level,rule,rule_en in [
('known-blankbody','Corpo Frio Identificado','Known Blankbody',2,'Biometria, nome, história, associados e nomes falsos constam em bancos de inteligência como potencial terrorista. Um inquisidor pode reconhecê-lo como vampiro.','Biometrics, name, history, associates and aliases appear in intelligence databases as a potential terrorist. An inquisitor may recognize you as a vampire.'),
('known-corpse','Cadáver Identificado','Known Corpse',1,'Pessoas sabem que morreu recentemente e reagem com choque e horror à sua presença. Pesquisas por sua identidade em bancos de dados também revelam isso.','People know you recently died and react with shock and horror to your presence. Database searches of your identity also reveal this.')]:
 add(slug,pt,en,'flaw',[192],rule,rule_en,fixed(level,rule,rule_en))
add('zeroed','Zerado','Zeroed','merit',[192],
'Alguém em altas posições eliminou seus registros reais. Você não existe oficialmente.',
'Someone in high places erased your real records. You do not officially exist.',fixed(1,'Exige Máscara 2.','Requires Mask 2.'),requirements={'itemRatings':{mask_id:2}})
add('cobbler','Sapateiro','Cobbler','merit',[192,194],
'Pode obter ou criar Máscaras. Fabricar leva três dias por ponto e pode expô-lo online. Obter leva um dia por ponto e tem um preço definido pelo Narrador, possivelmente por influência ou margem em teste Social.',
'Can obtain or create Masks. Creating takes three days per dot and may expose you online. Obtaining takes one day per dot and has a price set by the Storyteller, possibly through influence or a Social-test margin.',fixed(1,'Exige Máscara 2.','Requires Mask 2.'),requirements={'itemRatings':{mask_id:2}})
mawla_ranks=[('Neófito','Neonate'),('Ancilla','Ancilla'),('Ancião','Elder'),('Primogênito ou membro do Conselho Revolucionário Anarch','Primogen or Anarch Revolutionary Council member'),('Príncipe ou Barão','Prince or Baron')]
mawla=[]
for i,(pt,en) in enumerate(mawla_ranks,1):
 mawla.append((f'individual-{i}',i,pt,en,pt,en,{}));mawla.append((f'group-{i}',i+1,'Grupo: '+pt,'Group: '+en,'Grupo equivalente a '+pt+'.','A group equivalent to '+en+'.',{}))
add('mawla','Mawla','Mawla','background',[194,195],
'Membro ou grupo que oferece orientação, informações, ajuda esporádica, encobrimento e apoio político, esperando reciprocidade. Não luta suas batalhas nem paga favores altos. Forçá-lo além desses limites pode fazê-lo perder um ou mais pontos. Pode ser mentor ou Senhor e deve entrar no Mapa de Relacionamentos. Um grupo custa normalmente um ponto a mais que um único Membro equivalente.',
'A Kindred or group offering guidance, information, occasional help, cover-ups and political support, expecting reciprocity. Does not fight your battles or pay major favors. Pressing beyond these limits may cost one or more dots. May be a mentor or sire and belongs on the Relationship Map. A group normally costs one dot more than an equivalent individual Kindred.',mawla,repeat=True)
add('minor-boon','Favor Menor','Minor Boon','background',[195],
'Somente na criação pode adquirir Favores Menores de outros Membros. O custo é metade do Mawla equivalente, arredondada para cima. Não representa um mentor permanente; descreva a pessoa e o favor devido.',
'Only during creation may purchase Minor Boons owed by other Kindred. Cost is half the equivalent Mawla rating, rounded up. Does not represent a permanent mentor; describe the person and the owed favor.',[(i,(i+1)//2,pt,en,'Favor de '+pt+'.','A boon from '+en+'.',{}) for i,(pt,en) in enumerate(mawla_ranks,1)],repeat=True,requirements={'creationOnly':True})
add('adversary','Adversário','Adversary','flaw',[195],
'Cainita que quer o seu mal, ou o de seu Senhor, linhagem ou mentor. É o oposto de Mawla: de um ancião por 1 ponto a Príncipe ou cabala poderosa por 3. O Narrador pode usar Status ou outra Característica do Adversário no lugar do valor do Antecedente para formar paradas contra os personagens.',
'A Cainite wishing harm to you, your sire, bloodline or mentor. The opposite of Mawla: from an elder at 1 dot to a Prince or powerful cabal at 3. The Storyteller may use the Adversary’s Status or another trait instead of the Background rating to build pools against characters.',levels([('Ancião hostil.','A hostile elder.'),('Adversário intermediário; defina com o Narrador.','An intermediate adversary; define with the Storyteller.'),('Príncipe ou cabala poderosa.','A Prince or powerful cabal.')]),repeat=True)
add('resources','Recursos','Resources','background',[195],
'Status econômico, acesso à riqueza e renda para manter o padrão de não vida. Nem tudo é capital líquido: vender patrimônio pode levar semanas ou meses. Descreva a origem da renda e a forma dos bens, que podem ser roubados, esgotados ou perdidos durante a crônica. A Segunda Inquisição incentiva manter riqueza em bens, ouro ou arte em vez de contas rastreáveis.',
'Economic status, access to wealth and income maintaining a standard of unlife. Assets are not necessarily liquid: selling them may take weeks or months. Describe income sources and asset forms, which may be stolen, depleted or lost during the chronicle. The Second Inquisition encourages holding goods, gold or art rather than traceable accounts.',levels([
('Proletariado: vive de salário em salário; apartamento, carro, equipamento de camping.','Working class: paycheck to paycheck; apartment, car and camping equipment.'),('Classe Média: bom apartamento ou casa pequena, alguns carros e eletrodomésticos recentes.','Middle class: nice apartment or small house, a few cars and current appliances.'),('Rico: casa ou apartamento grande, luxo e equipamentos de última geração para várias pessoas.','Rich: large home or apartment, luxury and top equipment for several people.'),('Milionário: mansão, helicóptero ou jato particular e equipamentos especializados.','Wealthy: mansion, helicopter or private jet and specialized equipment.'),('Bilionário: várias mansões, qualquer coisa que o dinheiro possa comprar.','Extremely wealthy: multiple mansions, anything money can buy.')]),repeat=True,requirements={'incompatibleItems':['core-background-destitute']})
add('destitute','Destituído','Destitute','flaw',[195],'Não tem dinheiro nem casa.','Has neither money nor a home.',fixed(1,'Sem recursos materiais estáveis.','No stable material resources.'),requirements={'incompatibleItems':['core-background-resources']})
add('retainers','Lacaios','Retainers','background',[187,196],
'Servidores ou assistentes mantidos por salário, Vitae, Dominação ou outra influência. Geralmente leais, mas podem trair por recompensa maior ou maus-tratos. O Narrador pode exigir cenas com eles. Mesmo carniçais não são super-homens; são personagens, não fantoches.',
'Servants or assistants maintained through wages, vitae, Dominate or another influence. Usually loyal but may betray you for greater rewards or after mistreatment. The Storyteller may require scenes with them. Even ghouls are not superhuman; they are characters, not puppets.',levels([
('Lacaio decepcionante ou inexperiente: construa como mortal Fraco.','An underwhelming or inexperienced retainer: build as a Weak mortal.'),('Carniçal, servo da família, amante humano ou escravo dominado: mortal Médio ou carniçal sem Vantagens.','A ghoul, family servant, human lover or dominated slave: Average mortal or ghoul without Advantages.'),('Competente para agir sozinho e resolver pequenos problemas: provavelmente carniçal com características de mortal Talentoso e habilidades sobrenaturais.','Competent enough to act independently and solve minor problems: probably a ghoul with Gifted mortal traits and supernatural abilities.')]),repeat=True,extra=models_pt,extra_en=models_en)
add('stalkers','Perseguidores','Stalkers','flaw',[196],
'Atrai pessoas abusivas impressionadas com você, como um ex-criado que deseja se reconectar. Podem estar famintas, apaixonadas, desesperadas ou ser oportunistas. Quando se livra de uma, outra aparece.',
'Attracts abusive people impressed by you, such as a former servant wanting to reconnect. They may be hungry, infatuated, desperate or opportunistic. Getting rid of one brings another.',fixed(1,'Problema recorrente de relacionamento.','A recurring relationship problem.'))
add('status','Status','Status','background',[196],
'Reputação em uma comunidade local de Membros especificada, como uma seita. Na Camarilla pode derivar do Senhor, linhagem e realizações; entre Anarchs, das contribuições e conexões ao governante. Não se transfere entre seitas e em outra cidade costuma valer um ponto a menos. O Narrador pode somá-lo a uma Característica Social, especialmente em primeiras reuniões ou eventos da corte, ou permitir substituir uma Característica; outros vampiros podem notar o abuso. Caitiff não podem adquirir Status positivo na criação.',
'Reputation in a specified local Kindred community, such as a sect. In the Camarilla may derive from sire, lineage and achievements; among Anarchs, contributions and connections to the ruler. Does not transfer between sects and usually counts one dot lower in another city. The Storyteller may add it to a Social trait, especially at first meetings or court events, or allow replacing a trait; other vampires may notice abuse. Caitiff cannot purchase positive Status during creation.',levels([
('Conhecido: Neófito apresentado e recebido, visto como promissor.','Known: a properly introduced and welcomed neonate, seen as promising.'),('Respeitado: ancilla médio com responsabilidades.','Respected: an average ancilla with responsibilities.'),('Influente: ancião comum com autoridade sobre parte do grupo.','Influential: an ordinary elder with authority over part of the group.'),('Poderoso: cargo como Xerife, Harpia ou Algoz.','Powerful: an office such as Sheriff, Harpy or Scourge.'),('Luminar: senta-se com os poderosos, respeitado pela Primigênie.','Luminary: sits with the powerful, respected by the Primogen.')]),repeat=True,requirements={'creationExcludedClans':['Caitiff']})
add('shunned','Segregado','Shunned','flaw',[196],
'Completamente odiado pela seita por traição, oposição a líderes ou conflito passado. Seus membros trabalham ativamente contra você quando podem.',
'Completely hated by the sect for betrayal, opposition to leaders or past conflict. Its members actively work against you whenever possible.',fixed(2,'Defina a seita e a causa da hostilidade.','Specify the sect and reason for hostility.'),repeat=True)
add('suspect','Suspeito','Suspect','flaw',[196],
'Não se dá bem com a seita: traiu sua confiança, quebrou juramento ou algo semelhante. Até fazer as pazes, sofre −2 dados em todos os testes Sociais envolvendo a facção ofendida. Pode tentar ficar fora de vista para ser esquecido. Caitiff começam com este Defeito.',
'On poor terms with the sect after betraying trust, breaking an oath or similar. Until making amends, suffers −2 dice on all Social tests involving the offended faction. May try keeping out of sight to be forgotten. Caitiff begin with this Flaw.',fixed(1,'Defina a facção e a transgressão.','Specify the faction and transgression.'),repeat=True)
